        public void drawRGB(int[] rgbData, int offset, int scanlength, int x, int y, int width, int height, bool processAlpha)
        {
            if ((width <= 0) || (height <= 0))
            {
                return;
            }
            int ax = x + this.tx;
            int ay = y + this.ty;
            int[] d = this.target.data;
            for (int j = 0; (j < height); j++)
            {
                int yy = ay + j;
                if ((yy < this.cy0) || (yy >= this.cy1))
                {
                    continue;
                }
                for (int i = 0; (i < width); i++)
                {
                    int xx = ax + i;
                    if ((xx < this.cx0) || (xx >= this.cx1))
                    {
                        continue;
                    }
                    int c = rgbData[offset + j * scanlength + i];
                    int di = yy * this.tw + xx;
                    if (!processAlpha)
                    {
                        d[di] = c | -16777216;
                    }
                    else
                    {
                        d[di] = Graphics.blend(c, d[di]);
                    }
                }
            }
        }

        public void copyArea(int xSrc, int ySrc, int width, int height, int xDest, int yDest, int anchor)
        {
            if (!this.target.mutable)
            {
                throw new global::System.InvalidOperationException("copyArea on immutable");
            }
            int[] tmp = new int[width * height];
            int sx = xSrc + this.tx;
            int sy = ySrc + this.ty;
            for (int j = 0; (j < height); j++)
            {
                for (int i = 0; (i < width); i++)
                {
                    int px = sx + i;
                    int py = sy + j;
                    tmp[j * width + i] = ((px >= 0) && (py >= 0) && (px < this.tw) && (py < this.th) ? this.target.data[py * this.tw + px] : 0);
                }
            }
            int dx = Graphics.anchorX(xDest, width, anchor) + this.tx;
            int dy = Graphics.anchorY(yDest, height, anchor) + this.ty;
            for (int j_1 = 0; (j_1 < height); j_1++)
            {
                for (int i_1 = 0; (i_1 < width); i_1++)
                {
                    int px_1 = dx + i_1;
                    int py_1 = dy + j_1;
                    if ((px_1 >= this.cx0) && (px_1 < this.cx1) && (py_1 >= this.cy0) && (py_1 < this.cy1))
                    {
                        this.target.data[py_1 * this.tw + px_1] = tmp[j_1 * width + i_1];
                    }
                }
            }
        }

        // ---- text ----------------------------------------------------------------------------
        public void drawString(string str, int x, int y, int anchor)
        {
            if (str == null)
            {
                throw new global::System.NullReferenceException();
            }
            BitmapFont bf = this.font.bitmap();
            int w = this.font.stringWidth(str);
            int ax = Graphics.anchorX(x, w, anchor);
            int ay = 0;
            if ((anchor & Graphics.BASELINE) != 0)
            {
                ay = y - bf.baseline;
            }
            else if ((anchor & Graphics.BOTTOM) != 0)
            {
                ay = y - bf.height;
            }
            else
            {
                ay = y;
            }
            bf.draw(this.target.data, this.tw, this.cx0, this.cy0, this.cx1, this.cy1, str, ax + this.tx, ay + this.ty, this.color, this.font.isBold());
            if (this.font.isUnderlined())
            {
                int uy = ay + bf.baseline + 1;
                this.drawLine(ax, uy, ax + w - 1, uy);
            }
        }

        public void drawSubstring(string str, int offset, int len, int x, int y, int anchor)
        {
            this.drawString(str.substring(offset, offset + len), x, y, anchor);
        }

        public void drawChar(char character, int x, int y, int anchor)
        {
            this.drawString(J2ME.JString.valueOf(character), x, y, anchor);
        }

        public void drawChars(char[] data, int offset, int length, int x, int y, int anchor)
        {
            this.drawString(J2ME.JString.newString(data, offset, length), x, y, anchor);
        }
    }
}
